        {
          "find": "class GRU4RecModel(nn.Module):",
          "replace": "@torch.jit.script
def _residual_gru_steps(projected: torch.Tensor, hidden: torch.Tensor,
                        weight_hh: torch.Tensor, bias_hh: torch.Tensor):
    states = torch.jit.annotate(list[torch.Tensor], [])
    for t in range(projected.size(1)):
        input_r, input_z, input_n = projected[:, t].chunk(3, dim=-1)
        hidden_r, hidden_z, hidden_n = torch.nn.functional.linear(
            hidden, weight_hh, bias_hh
        ).chunk(3, dim=-1)
        reset = torch.sigmoid(input_r + hidden_r)
        update = torch.sigmoid(input_z + hidden_z)
        candidate = torch.tanh(input_n + reset * hidden_n)
        gru_hidden = (1.0 - update) * candidate + update * hidden
        hidden = 0.95 * gru_hidden + 0.05 * hidden
        states.append(hidden)
    return torch.stack(states, dim=1), hidden


class ResidualMemoryGRU(nn.GRU):
    def forward(self, input: torch.Tensor, hx=None):
        layer_input = input if self.batch_first else input.transpose(0, 1)
        if hx is None:
            hx = layer_input.new_zeros(
                self.num_layers, layer_input.size(0), self.hidden_size
            )
        final_states = []
        for layer in range(self.num_layers):
            projected = torch.nn.functional.linear(
                layer_input,
                getattr(self, f'weight_ih_l{layer}'),
                getattr(self, f'bias_ih_l{layer}'),
            )
            layer_input, last_hidden = _residual_gru_steps(
                projected, hx[layer],
                getattr(self, f'weight_hh_l{layer}'),
                getattr(self, f'bias_hh_l{layer}'),
            )
            final_states.append(last_hidden)
            if layer + 1 < self.num_layers and self.dropout > 0.0:
                layer_input = torch.nn.functional.dropout(
                    layer_input, p=self.dropout, training=self.training
                )
        output = layer_input if self.batch_first else layer_input.transpose(0, 1)
        return output, torch.stack(final_states, dim=0)


class GRU4RecModel(nn.Module):"
